  let abortState={tank:null,row:null,colors:null,order:null,material:null,amount:''};
  const el=id=>document.getElementById(id);
  const auth=()=>typeof personnelSessionMatchesSelection==='function'&&personnelSessionMatchesSelection();
  const person=()=>selectedPersonnel||null;
