  function refreshFa(){if(!faState.row||!faState.material)return;const n=faAmount(),available=Number(faState.row.quantityKg||0),allowed=faState.material.mkBookingAllowed===true,valid=allowed&&Number.isFinite(n)&&n>0&&n<=available+.0005&&!busy;el('faBookStep').classList.toggle('lockedStep',!valid);el('faBookBtn').disabled=!valid;if(!allowed)setStatus('faAmountStatus','MK ist für diesen Materialstatus gesperrt.','bad');else if(n===null)setStatus('faAmountStatus',`Zusätzlichen Verbrauch eingeben. Tankbestand ${qty(available)} kg.`);else if(!Number.isFinite(n)||n<=0)setStatus('faAmountStatus','⛔ Verbrauch muss größer als 0 kg sein.','bad');else if(n>available+.0005)setStatus('faAmountStatus',`⛔ Verbrauch ist größer als Tankbestand ${qty(available)} kg.`,'bad');else setStatus('faAmountStatus',`✓ Zusätzlicher Verbrauch ${qty(n)} kg. Erwarteter kumulierter Verbrauch danach: ${qty(Number(faState.material.consumedKg)+n)} kg.`,'ok');el('faSummary').innerHTML=`<b>${html(faState.order.orderNo)} · Pos. ${html(faState.material.materialPosition)}</b><br>Soll: ${qty(faState.material.requiredKg)} kg · bereits gebucht: <b>${qty(faState.material.consumedKg)} kg</b><br>Zusätzlich jetzt: <b>${n&&Number.isFinite(n)?qty(n)+' kg':'fehlt'}</b><br>Tank ${html(faState.tank.warehouse)} · Mix ${html(faState.row.batch)}`;setInstruction(valid?'FA-Verbrauch prüfen und buchen.':'Zusätzlichen Verbrauch eingeben.');}
